// Maps a raw Gmail messages.get payload to the normalized `emails` row shape.
// Input item: { account_id, raw_message }
// Output item: { account_id, provider, provider_message_id, thread_id, participants, subject, body, raw_payload, labels, received_at }

function decodeBase64Url(data) {
  if (!data) return '';
  const normalized = data.replace(/-/g, '+').replace(/_/g, '/');
  return Buffer.from(normalized, 'base64').toString('utf-8');
}

// Splits a header like "Name <a@b.com>, other@b.com" into address parts.
// Simple comma split is sufficient here: quoted display names containing
// commas are not expected in this pipeline's inputs (out of scope, per task).
function parseAddressList(headerValue, role) {
  if (!headerValue) return [];
  return headerValue
    .split(',')
    .map((part) => part.trim())
    .filter(Boolean)
    .map((part) => {
      const match = part.match(/^(.*)<(.+)>$/);
      if (match) {
        const name = match[1].trim().replace(/^"|"$/g, '');
        const address = match[2].trim();
        return { role, name: name || null, address };
      }
      return { role, name: null, address: part };
    });
}

function getHeader(headers, headerName) {
  const found = (headers || []).find(
    (h) => (h.name || '').toLowerCase() === headerName.toLowerCase()
  );
  return found ? found.value : null;
}

// Depth-first search for the first part matching a MIME type (handles
// both flat multipart/alternative and nested multipart structures).
function findPartByMimeType(parts, mimeType) {
  if (!parts) return null;
  for (const part of parts) {
    if (part.mimeType === mimeType && part.body && part.body.data) {
      return part;
    }
    if (part.parts) {
      const nested = findPartByMimeType(part.parts, mimeType);
      if (nested) return nested;
    }
  }
  return null;
}

const input = $input.item.json;
const accountId = input.account_id;
const rawMessage = input.raw_message;

const payload = rawMessage.payload || {};
const headers = payload.headers || [];

const fromHeader = getHeader(headers, 'From');
const toHeader = getHeader(headers, 'To');
const ccHeader = getHeader(headers, 'Cc');

const participants = [
  ...parseAddressList(fromHeader, 'from'),
  ...parseAddressList(toHeader, 'to'),
  ...parseAddressList(ccHeader, 'cc'),
];

const subject = getHeader(headers, 'Subject');

// Prefer text/plain. Fall back to text/html as-is (no HTML stripping - out
// of scope). Fall back to a non-multipart message's top-level body as a
// last resort.
let body = '';
const plainPart = findPartByMimeType(payload.parts, 'text/plain');
if (plainPart) {
  body = decodeBase64Url(plainPart.body.data);
} else {
  const htmlPart = findPartByMimeType(payload.parts, 'text/html');
  if (htmlPart) {
    body = decodeBase64Url(htmlPart.body.data);
  } else if (payload.body && payload.body.data) {
    body = decodeBase64Url(payload.body.data);
  }
}

const receivedAt = rawMessage.internalDate
  ? new Date(Number(rawMessage.internalDate)).toISOString()
  : null;

return {
  json: {
    account_id: accountId,
    provider: 'gmail',
    provider_message_id: rawMessage.id,
    thread_id: rawMessage.threadId || null,
    participants,
    subject: subject || null,
    body: body || null,
    raw_payload: rawMessage,
    labels: rawMessage.labelIds || [],
    received_at: receivedAt,
  },
};

// Upsert email returns one row with `id` when the INSERT succeeded, or an
// empty item (thanks to alwaysOutputData on that node) when ON CONFLICT DO
// NOTHING skipped the insert because the row already existed.
const row = $input.item.json || {};
const emailId = row.id || null;

return {
  json: {
    email_id: emailId,
    inserted: Boolean(emailId),
  },
};
